from math import gcd

def solve():
    n = int(input())
    arr = list(map(int, input().split()))
    def check_beautiful(n, arr):
        dp = [False] * (n + 1)
        dp[0] = True
        for i in range(1, n + 1):
            for j in range(i):
                if gcd(arr[i], arr[j]) <= i:
                    dp[i] = dp[i] or dp[i - gcd(arr[i], arr[j])]
        return dp[n]
    print("Yes" if check_beautiful(n, arr) else "No")

