from functools import lru_cache

def solve(s):
    @lru_cache(maxsize=1)
    def dfs(t, idx, k, curr, total):
        if idx >= len(s):
            return 0
        if curr >= len(s) * 3:
            return 1
        if k == 0:
            return float('inf')
        if k < 0 or idx == len(s):
            return float('inf')
        res = float('inf')
        res = min(res, dfs(t, idx+1, k-1, curr + ord(s[idx]) - ord('a')+1, total+1))
        res = min(res, dfs(t, idx+1, k-1, curr + ord(s[idx]) - ord('a')+1, total+1))
        if k == 1 and idx < len(s):
            res = min(res, dfs(t, idx+1, 0, curr+1, total+1))
        return res

    return dfs(2, 0, 3, 0, 0)

